package com.terrassic.registry;

import com.terrassic.Terrassic;
import dev.architectury.registry.registries.DeferredRegister;
import dev.architectury.registry.registries.RegistrySupplier;
import net.minecraft.core.registries.Registries;
import net.minecraft.sounds.SoundEvent;

/**
 * The mod's own sounds, organised in voice sets shared by many species (assets/terrassic/sounds.json).
 *
 * Generated by tools/soundgen/build.py - edit tools/soundgen/recipes.py.
 */
public final class ModSounds {
    public static final DeferredRegister<SoundEvent> SOUNDS = DeferredRegister.create(Terrassic.MOD_ID, Registries.SOUND_EVENT);

    public static final RegistrySupplier<SoundEvent> BOOM_LARGE_AMBIENT = register("voice.boom_large.ambient");
    public static final RegistrySupplier<SoundEvent> BOOM_LARGE_THREAT = register("voice.boom_large.threat");
    public static final RegistrySupplier<SoundEvent> BOOM_LARGE_HURT = register("voice.boom_large.hurt");
    public static final RegistrySupplier<SoundEvent> BOOM_LARGE_DEATH = register("voice.boom_large.death");
    public static final RegistrySupplier<SoundEvent> BOOM_LARGE_STEP = register("voice.boom_large.step");
    public static final RegistrySupplier<SoundEvent> HORN_HADROSAUR_AMBIENT = register("voice.horn_hadrosaur.ambient");
    public static final RegistrySupplier<SoundEvent> HORN_HADROSAUR_HURT = register("voice.horn_hadrosaur.hurt");
    public static final RegistrySupplier<SoundEvent> HORN_HADROSAUR_DEATH = register("voice.horn_hadrosaur.death");
    public static final RegistrySupplier<SoundEvent> SQUAWK_PTEROSAUR_AMBIENT = register("voice.squawk_pterosaur.ambient");
    public static final RegistrySupplier<SoundEvent> SQUAWK_PTEROSAUR_HURT = register("voice.squawk_pterosaur.hurt");
    public static final RegistrySupplier<SoundEvent> SQUAWK_PTEROSAUR_DEATH = register("voice.squawk_pterosaur.death");
    public static final RegistrySupplier<SoundEvent> SQUAWK_PTEROSAUR_FLAP = register("voice.squawk_pterosaur.flap");

    private ModSounds() {
    }

    private static RegistrySupplier<SoundEvent> register(String name) {
        return SOUNDS.register(name, () -> SoundEvent.createVariableRangeEvent(Terrassic.id(name)));
    }
}
